_COOKIES_INITIALIZED = False


def setup_cookies():
    global _COOKIES_INITIALIZED
    if _COOKIES_INITIALIZED:
        return

    cookie_candidates = [
        getattr(settings, "BASE_DIR", "") and os.path.join(settings.BASE_DIR, "cookies.txt"),
        os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "cookies.txt"),
        "/var/www/YouTube-Downloader/cookies.txt",
        "/tmp/cookies.txt",
    ]
    cookie_path = None
    for p in cookie_candidates:
        if p and os.path.exists(p) and os.path.getsize(p) > 10:
            cookie_path = p
            break

    if not cookie_path:
        cookie_path = "/tmp/cookies.txt"
        try:
            with open(cookie_path, "w", encoding="utf-8") as f:
                f.write(DEFAULT_COOKIES.strip() + "\n")
        except Exception:
            pass

    if cookie_path and os.path.exists(cookie_path):
        try:
            cj = http.cookiejar.MozillaCookieJar(cookie_path)
            cj.load(ignore_discard=True, ignore_expires=True)
            opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cj))
            urllib.request.install_opener(opener)
            _COOKIES_INITIALIZED = True
        except Exception as e:
            print("Cookie setup exception:", e)


def is_valid_youtube_url(video_url):
    """
    Check whether the URL looks like a YouTube URL.
    """
    if not video_url:
        return False
    pattern = r"^(https?://)?((www|m|music)\.)?(youtube\.com|youtu\.be)(/.+)?$"
    return re.match(pattern, video_url.strip()) is not None


def get_video_data(video_url):
    """
    Extract YouTube video information using pytubefix.
    Ensures authenticated session cookies are attached to bypass bot detection on datacenter IPs.
    Tries multiple client profiles (WEB, ANDROID, MWEB, IOS, TV_EMBED) for maximum reliability.
    """
    setup_cookies()
    video_url = video_url.strip()
    yt = None
    last_err = None

    for client_name in ["WEB", "ANDROID", "MWEB", "IOS", "TV_EMBED"]:
        try:
            candidate_yt = YouTube(video_url, client=client_name)
            # test stream access to ensure signatures decrypt properly
            _ = candidate_yt.streams
            yt = candidate_yt
            break
        except Exception as e:
            last_err = e
            continue

    if yt is None:
        if last_err:
            raise last_err
        raise RuntimeError("Unable to extract video details.")

    video_streams = []
    audio_streams = []
    seen_video_keys = set()
    seen_audio_keys = set()

    for stream in yt.streams:
        ext = getattr(stream, "subtype", "mp4") or "mp4"

        filesize = getattr(stream, "filesize", None) or getattr(stream, "filesize_approx", None)
        if filesize:
            try:
                file_size_str = f"{round(int(filesize) / (1024 * 1024), 2)} MB"
            except Exception:
                file_size_str = "Unknown"
        else:
            file_size_str = "Unknown"

        stream_url = getattr(stream, "url", None)
        if not stream_url:
            continue

        resolution = getattr(stream, "resolution", None)
        if resolution:
            key = (resolution, ext)
            if key not in seen_video_keys:
                seen_video_keys.add(key)
                res_num = 0
                try:
                    res_num = int(re.sub(r"\D", "", resolution) or 0)
                except Exception:
                    pass
                video_streams.append({
                    "resolution": resolution,
                    "height": res_num,
                    "extension": ext,
                    "file_size": file_size_str,
                    "video_url": stream_url,
                })
        else:
            abr = getattr(stream, "abr", "") or ""
            key = (ext, abr)
            if key not in seen_audio_keys:
                seen_audio_keys.add(key)
                audio_streams.append({
                    "extension": ext,
                    "file_size": file_size_str,
                    "video_url": stream_url,
                })

    video_streams.sort(key=lambda s: s.get("height", 0), reverse=True)

    duration = 0
    if getattr(yt, "length", None):
        try:
            duration = round(int(yt.length) / 60, 2)
        except Exception:
            duration = 0

    views = "0"
    if getattr(yt, "views", None):
        try:
            views = f"{int(yt.views):,}"
        except Exception:
            views = "0"

    context = {
        "title": getattr(yt, "title", "Unknown Title") or "Unknown Title",
        "author": getattr(yt, "author", "") or "",
        "streams": video_streams,
        "stream_audio": audio_streams,
        "description": getattr(yt, "description", "") or "",
        "likes": 0,
        "dislikes": 0,
        "thumb": getattr(yt, "thumbnail_url", "") or "",
        "duration": duration,
        "views": views,
    }
    return context


def download_video(request):
    form = DownloadForm(request.POST or None)
    if form.is_valid():
        video_url = form.cleaned_data.get("url")
        print("YouTube URL:", video_url)

        if not is_valid_youtube_url(video_url):
            return HttpResponse("Enter correct YouTube URL.")

        try:
            context = get_video_data(video_url)
            context["form"] = form
            return render(request, "home.html", context)
        except Exception as e:
            print("ERROR:", e)
            return HttpResponse(
                f"Unable to fetch video information.<br><br>Error: {str(e)}"
            )

    return render(request, "home.html", {"form": form})


